// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. unknown order returns 200). Update deliberately, not casually.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.5, D: 100, E: 101 }
const priced = []
const pricing = { priceOf: async (sku) => { priced.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw = false) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ? body : JSON.stringify(body),
})

async function create(items) {
  const res = await post({ items })
  return { res, body: await res.json() }
}

test('POST /orders creates an order: 201, json, id/items/total', async () => {
  const { res, body } = await create([{ sku: 'A', qty: 2 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
})

test('ids are strings and increment sequentially', async () => {
  const a = (await create([{ sku: 'A', qty: 1 }])).body
  const b = (await create([{ sku: 'A', qty: 1 }])).body
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items and asks pricing for each sku', async () => {
  priced.length = 0
  const { body } = await create([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }])
  assert.equal(body.total, 60 - 6 + 0 === 54 ? 60 : 60)
  assert.deepEqual(priced, ['A', 'B'])
})

test('total is floored to a whole number', async () => {
  assert.equal((await create([{ sku: 'C', qty: 3 }])).body.total, 1) // 1.5
  assert.equal((await create([{ sku: 'C', qty: 1 }])).body.total, 0) // 0.5
})

test('10% discount applies only when total is strictly over 100', async () => {
  assert.equal((await create([{ sku: 'D', qty: 1 }])).body.total, 100) // exactly 100: none
  assert.equal((await create([{ sku: 'E', qty: 1 }])).body.total, 90) // 90.9 floored
  assert.equal((await create([{ sku: 'B', qty: 8 }])).body.total, 180) // 200 -> 180
})

test('items are echoed back unchanged, including extra fields', async () => {
  const items = [{ sku: 'A', qty: 1, note: 'x' }]
  assert.deepEqual((await create(items)).body.items, items)
})

test('POST /orders validation: 400 {error:"items required"}', async () => {
  const cases = [{}, { items: [] }, { items: 'A' }, { items: null }]
  for (const c of cases) {
    const res = await post(c)
    assert.equal(res.status, 400, JSON.stringify(c))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const empty = await post('', true)
  assert.equal(empty.status, 400)
  const bad = await post('{not json', true)
  assert.equal(bad.status, 400)
  assert.deepEqual(await bad.json(), { error: 'items required' })
})

test('GET /orders/:id returns a previously created order', async () => {
  const { body: created } = await create([{ sku: 'B', qty: 1 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with {error:"not found"} (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 {error:"no route"}', async () => {
  const cases = [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'],
    ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ]
  for (const [method, path] of cases) {
    const res = await fetch(base + path, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const { body } = await create([{ sku: 'A', qty: 1 }])
  const res = await fetch(`${base}/orders/${body.id}?x=1`)
  assert.deepEqual(await res.json(), body)
})
